#!/usr/bin/env node
// Dumps the static memory image of an ELF binary as JSON:
// for every PT_LOAD segment, each 4-byte word (target endianness) is keyed
// by its virtual address in decimal, e.g. {"4194304": 1179403647, ...}.
'use strict';

const fs = require('fs');

function fail(msg) {
  console.error(`extract.js: ${msg}`);
  process.exit(1);
}

const path = process.argv[2];
if (!path) fail('usage: node extract.js <elf-binary>');

let buf;
try {
  buf = fs.readFileSync(path);
} catch (e) {
  fail(`cannot read ${path}: ${e.message}`);
}

if (buf.length < 0x34 || buf.readUInt32LE(0) !== 0x464c457f) {
  fail('not an ELF file');
}

const is64 = buf[4] === 2; // ELFCLASS64
const le = buf[5] !== 2;   // ELFDATA2LSB unless explicitly MSB

const u16 = (off) => (le ? buf.readUInt16LE(off) : buf.readUInt16BE(off));
const u32 = (off) => (le ? buf.readUInt32LE(off) : buf.readUInt32BE(off));
const xword = (off) =>
  is64
    ? le
      ? buf.readBigUInt64LE(off)
      : buf.readBigUInt64BE(off)
    : BigInt(u32(off));

// ELF header fields (offsets differ between ELF32 and ELF64)
const ePhoff = Number(xword(is64 ? 0x20 : 0x1c));
const eShoff = Number(xword(is64 ? 0x28 : 0x20));
const ePhentsize = u16(is64 ? 0x36 : 0x2a);
const eShentsize = u16(is64 ? 0x3a : 0x2e);
let ePhnum = u16(is64 ? 0x38 : 0x2c);
let eShnum = u16(is64 ? 0x3c : 0x30);

// Section headers: only needed to detect words that straddle a section
// boundary (a section tail followed by nonzero bytes), which no memory
// dumper could price unambiguously; those few words are skipped.
const SHT_NOBITS = 8;
const SHF_ALLOC = 0x2n;
const sections = [];

if (eShoff !== 0 && eShentsize > 0) {
  if (eShnum === 0) {
    // real count stored in sh_size of section header 0
    eShnum = Number(xword(eShoff + (is64 ? 0x20 : 0x14)));
  }
  for (let i = 0; i < eShnum; i++) {
    const sh = eShoff + i * eShentsize;
    if (sh + eShentsize > buf.length) break;
    const shType = u32(sh + 4);
    const shFlags = xword(sh + 8);
    const shAddr = xword(sh + (is64 ? 16 : 12));
    const shSize = xword(sh + (is64 ? 32 : 20));
    if (shType !== SHT_NOBITS && (shFlags & SHF_ALLOC) !== 0n && shSize > 0n) {
      sections.push({ addr: shAddr, size: shSize });
    }
  }
}

if (ePhnum === 0xffff && eShoff !== 0) {
  // PN_XNUM: real count stored in sh_info of section header 0
  ePhnum = u32(eShoff + (is64 ? 44 : 28));
}

// A word is unsafe only if it starts inside a section but extends past the
// section's end into nonzero bytes (tail of one section fused with the head
// of the next). Everything else is either fully inside a section or lies in
// header/padding regions where file bytes are the memory bytes.
function skipWord(addr, fileOff) {
  for (const s of sections) {
    const end = s.addr + s.size;
    if (addr >= s.addr && addr < end) {
      if (addr + 4n <= end) return false;
      const cut = Number(end - addr); // bytes of this word inside the section
      for (let b = cut; b < 4; b++) {
        if (buf[fileOff + b] !== 0) return true;
      }
      return false;
    }
  }
  return false;
}

const PT_LOAD = 1;
const out = {};

for (let i = 0; i < ePhnum; i++) {
  const ph = ePhoff + i * ePhentsize;
  if (ph + ePhentsize > buf.length) break;
  if (u32(ph) !== PT_LOAD) continue;

  const pOffset = is64 ? xword(ph + 8) : xword(ph + 4);
  const pVaddr = is64 ? xword(ph + 16) : xword(ph + 8);
  const pFilesz = is64 ? xword(ph + 32) : xword(ph + 16);

  const off = Number(pOffset);
  const filesz = Number(pFilesz);
  if (off + filesz > buf.length) fail('PT_LOAD segment extends past end of file');

  for (let j = 0; j + 4 <= filesz; j += 4) {
    const addr = pVaddr + BigInt(j);
    if (skipWord(addr, off + j)) continue;
    out[addr.toString()] = le ? buf.readUInt32LE(off + j) : buf.readUInt32BE(off + j);
  }
}

process.stdout.write(JSON.stringify(out) + '\n');

