cd /app && python3 - <<'EOF'
import json, struct

data = open('a.out','rb').read()
ours = json.load(open('out.json'))

# --- independent ELF64 LE parse ---
e_phoff, = struct.unpack_from('<Q', data, 0x20)
e_shoff, = struct.unpack_from('<Q', data, 0x28)
e_phentsize, = struct.unpack_from('<H', data, 0x36)
e_phnum, = struct.unpack_from('<H', data, 0x38)
e_shentsize, = struct.unpack_from('<H', data, 0x3a)
e_shnum, = struct.unpack_from('<H', data, 0x3c)

segs = []
for i in range(e_phnum):
    t, fl, off, va, pa, fsz, msz, al = struct.unpack_from('<IIQQQQQ', data, e_phoff + i*e_phentsize)
    if t == 1: segs.append((off, va, fsz, msz))

secs = []
for i in range(e_shnum):
    name, st, fl, addr, off, size = struct.unpack_from('<IIQQQQ', data, e_shoff + i*e_shentsize)[:6]
    secs.append((st, fl, addr, off, size))

# Hypothesis A: segment-based oracle (full words + short trailing partial, zero-padded)
oracleA = {}
for off, va, fsz, msz in segs:
    i = 0
    while i < fsz:
        chunk = data[off+i:off+i+4]
        oracleA[va+i] = int.from_bytes(chunk, 'little')
        i += 4
    # bss tail
    i = fsz
    while i < msz:
        oracleA[va+i] = 0
        i += 4

# Hypothesis B: section-based oracle (alloc, non-nobits, short partials)
oracleB = {}
for st, fl, addr, off, size in secs:
    if fl & 0x2 and st != 8:
        i = 0
        while i < size:
            oracleB[addr+i] = int.from_bytes(data[off+i:off+i+4], 'little')
            i += 4

def check(oracle, name):
    ok = bad = 0
    badkeys = []
    for k, v in ours.items():
        a = int(k)
        if a in oracle:
            if oracle[a] == v: ok += 1
            else: bad += 1; badkeys.append((hex(a), v, oracle[a]))
    cov = ok / len(oracle) * 100
    print(f'{name}: oracle keys={len(oracle)}, our matching+correct={ok}, MISMATCH={bad}, coverage={cov:.1f}%')
    for b in badkeys[:10]: print('   mismatch:', b)

check(oracleA, 'A: segment-based (incl. bss+partials)')
check(oracleB, 'B: section-based (incl. short partials)')

# exact full-word segment dump equality
full = {str(va+i): int.from_bytes(data[off+i:off+i+4],'little')
        for off, va, fsz, msz in segs for i in range(0, fsz-3, 4)}
diff = {k for k in full if k not in ours} | {k for k in ours if k not in full}
print('diff vs exact full-word segment dump:', sorted(diff, key=int) or 'NONE')
print('value mismatches vs full-word dump:', [k for k in full if k in ours and full[k]!=ours[k]] or 'NONE')
EOF

